namespace sv_6da9da5d76924c6f849cd2a38afec739.Client.Services;

public interface IShipmentService
{
    Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

public record ShipmentDetails(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> Updates);

public record StatusUpdate(string Description, DateTimeOffset Timestamp);

using sv_6da9da5d76924c6f849cd2a38afec739.Client.Services;

namespace sv_6da9da5d76924c6f849cd2a38afec739.Services;

public sealed class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, ShipmentDetails> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new ShipmentDetails(
            "TRK-001",
            "In Transit",
            "Memphis, TN",
            new DateTimeOffset(2026, 6, 20, 17, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Package picked up", new DateTimeOffset(2026, 6, 14, 9, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Arrived at sorting facility", new DateTimeOffset(2026, 6, 15, 3, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("In transit to destination", new DateTimeOffset(2026, 6, 16, 11, 0, 0, TimeSpan.Zero)),
            ]),
        ["TRK-002"] = new ShipmentDetails(
            "TRK-002",
            "Delivered",
            "Seattle, WA",
            new DateTimeOffset(2026, 6, 15, 12, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Package picked up", new DateTimeOffset(2026, 6, 12, 8, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("In transit", new DateTimeOffset(2026, 6, 13, 14, 0, 0, TimeSpan.Zero)),
                new StatusUpdate("Out for delivery", new DateTimeOffset(2026, 6, 15, 7, 30, 0, TimeSpan.Zero)),
                new StatusUpdate("Delivered", new DateTimeOffset(2026, 6, 15, 11, 42, 0, TimeSpan.Zero)),
            ]),
        ["TRK-003"] = new ShipmentDetails(
            "TRK-003",
            "Processing",
            "Austin, TX",
            new DateTimeOffset(2026, 6, 22, 18, 0, 0, TimeSpan.Zero),
            [
                new StatusUpdate("Label created", new DateTimeOffset(2026, 6, 16, 16, 0, 0, TimeSpan.Zero)),
            ]),
    };

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
    }
}

@page "/shipments/{TrackingNumber}"
@rendermode InteractiveAuto
@using sv_6da9da5d76924c6f849cd2a38afec739.Client.Services
@inject IShipmentService ShipmentService
@inject ILogger<ShipmentTracker> Logger
@implements IDisposable

<PageTitle>Shipment @TrackingNumber</PageTitle>

@if (_loading)
{
    <div class="loading-placeholder">
        <p><em>Loading shipment details for @TrackingNumber&hellip;</em></p>
    </div>
}
else if (_errorMessage is not null)
{
    <div class="alert alert-danger">
        <p>@_errorMessage</p>
        <button class="btn btn-primary" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_shipment is not null)
{
    <h2>Shipment @_shipment.TrackingNumber</h2>
    <dl>
        <dt>Status</dt>
        <dd>@_shipment.Status</dd>
        <dt>Location</dt>
        <dd>@_shipment.Location</dd>
        <dt>Estimated Delivery</dt>
        <dd>@_shipment.EstimatedDelivery.ToString("f")</dd>
    </dl>

    <h3>Tracking History</h3>
    <ul>
        @foreach (var update in _shipment.Updates)
        {
            <li><strong>@update.Timestamp.ToString("g")</strong> &mdash; @update.Description</li>
        }
    </ul>
}

@code {
    [Parameter]
    public string TrackingNumber { get; set; } = default!;

    private ShipmentDetails? _shipment;
    private bool _loading;
    private string? _errorMessage;

    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        await LoadShipmentAsync();
    }

    private async Task LoadShipmentAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var ct = _cts.Token;

        _shipment = null;
        _errorMessage = null;
        _loading = true;
        StateHasChanged();

        try
        {
            _shipment = await ShipmentService.GetShipmentAsync(TrackingNumber, ct);
        }
        catch (OperationCanceledException) when (ct.IsCancellationRequested)
        {
            // Navigation changed or component disposed; do nothing
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex) when (ex is not OperationCanceledException)
        {
            Logger.LogError(ex, "Error loading shipment {TrackingNumber}", TrackingNumber);
            _errorMessage = "Something went wrong while loading shipment details. Please try again.";
        }
        finally
        {
            _loading = false;
            StateHasChanged();
        }
    }

    private async Task RetryAsync()
    {
        await LoadShipmentAsync();
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

